7	import { promises as fs } from 'node:fs';
8	import * as path from 'node:path';
9	import * as os from 'node:os';
10	import * as crypto from 'node:crypto';
11	import type { Keychain } from './keychainTypes.js';
12	import { GEMINI_DIR, homedir } from '../utils/paths.js';
13	
14	export class FileKeychain implements Keychain {
15	  private readonly tokenFilePath: string;
16	  private readonly encryptionKey: Buffer;
17	
18	  constructor() {
19	    const configDir = path.join(homedir(), GEMINI_DIR);
20	    this.tokenFilePath = path.join(configDir, 'gemini-credentials.json');
21	    this.encryptionKey = this.deriveEncryptionKey();
22	  }
23	
24	  private deriveEncryptionKey(): Buffer {
25	    const salt = `${os.hostname()}-${os.userInfo().username}-gemini-cli`;
26	    return crypto.scryptSync('gemini-cli-oauth', salt, 32);
27	  }
28	
29	  private encrypt(text: string): string {
30	    const iv = crypto.randomBytes(16);
31	    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);
32	
33	    let encrypted = cipher.update(text, 'utf8', 'hex');
34	    encrypted += cipher.final('hex');
35	
36	    const authTag = cipher.getAuthTag();
37	
38	    return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;
39	  }
40	
41	  private decrypt(encryptedData: string): string {
42	    const parts = encryptedData.split(':');
43	    if (parts.length !== 3) {
44	      throw new Error('Invalid encrypted data format');
45	    }
46	
47	    const iv = Buffer.from(parts[0], 'hex');
48	    const authTag = Buffer.from(parts[1], 'hex');
49	    const encrypted = parts[2];
50	
51	    const decipher = crypto.createDecipheriv(
52	      'aes-256-gcm',
53	      this.encryptionKey,
54	      iv,
55	    );
56	    decipher.setAuthTag(authTag);
57	
58	    let decrypted = decipher.update(encrypted, 'hex', 'utf8');
59	    decrypted += decipher.final('utf8');
60	
61	    return decrypted;
62	  }
63	
64	  private async ensureDirectoryExists(): Promise<void> {
65	    const dir = path.dirname(this.tokenFilePath);
66	    await fs.mkdir(dir, { recursive: true, mode: 0o700 });
67	  }
68	
69	  private async loadData(): Promise<Record<string, Record<string, string>>> {
70	    try {
71	      const data = await fs.readFile(this.tokenFilePath, 'utf-8');
72	      const decrypted = this.decrypt(data);
73	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
74	      return JSON.parse(decrypted) as Record<string, Record<string, string>>;
75	    } catch (error: unknown) {
76	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
77	      const err = error as NodeJS.ErrnoException & { message?: string };
78	      if (err.code === 'ENOENT') {
79	        return {};
80	      }
81	      if (
82	        err.message?.includes('Invalid encrypted data format') ||
83	        err.message?.includes(
84	          'Unsupported state or unable to authenticate data',
85	        )
86	      ) {
87	        throw new Error(
88	          `Corrupted credentials file detected at: ${this.tokenFilePath}\n` +
89	            `Please delete or rename this file to resolve the issue.`,
90	        );
91	      }
92	      throw error;
93	    }
94	  }
95	
96	  private async saveData(
97	    data: Record<string, Record<string, string>>,
98	  ): Promise<void> {
99	    await this.ensureDirectoryExists();
100	    const json = JSON.stringify(data, null, 2);
101	    const encrypted = this.encrypt(json);
102	    await fs.writeFile(this.tokenFilePath, encrypted, { mode: 0o600 });
103	  }
104	
105	  async getPassword(service: string, account: string): Promise<string | null> {
106	    const data = await this.loadData();
107	    return data[service]?.[account] ?? null;
108	  }
109	
110	  async setPassword(
111	    service: string,
112	    account: string,
113	    password: string,
114	  ): Promise<void> {
115	    const data = await this.loadData();
116	    if (!data[service]) {
117	      data[service] = {};
118	    }
119	    data[service][account] = password;
120	    await this.saveData(data);
121	  }
122	
123	  async deletePassword(service: string, account: string): Promise<boolean> {
124	    const data = await this.loadData();
125	    if (data[service] && account in data[service]) {
126	      delete data[service][account];
127	
128	      if (Object.keys(data[service]).length === 0) {
129	        delete data[service];
130	      }
131	
132	      if (Object.keys(data).length === 0) {
133	        try {
134	          await fs.unlink(this.tokenFilePath);
135	        } catch (error: unknown) {
136	          // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
137	          const err = error as NodeJS.ErrnoException;
138	          if (err.code !== 'ENOENT') {
139	            throw error;
140	          }
141	        }
142	      } else {
143	        await this.saveData(data);
144	      }
145	      return true;
146	    }
147	    return false;
148	  }
149	
150	  async findCredentials(
151	    service: string,
152	  ): Promise<Array<{ account: string; password: string }>> {
153	    const data = await this.loadData();
154	    const serviceData = data[service] || {};
155	    return Object.entries(serviceData).map(([account, password]) => ({
156	      account,
157	      password,
158	    }));
159	  }
160	}
