7	import { z } from 'zod';
8	
9	/**
10	 * Interface for OS-level secure storage operations.
11	 * Note: Method names must match the underlying library (e.g. keytar)
12	 * to support correct dynamic loading and schema validation.
13	 */
14	export interface Keychain {
15	  getPassword(service: string, account: string): Promise<string | null>;
16	  setPassword(
17	    service: string,
18	    account: string,
19	    password: string,
20	  ): Promise<void>;
21	  deletePassword(service: string, account: string): Promise<boolean>;
22	  findCredentials(
23	    service: string,
24	  ): Promise<Array<{ account: string; password: string }>>;
25	}
