87	/**
88	 * Resolves the workspace policy state by checking folder trust and policy integrity.
89	 */
90	export async function resolveWorkspacePolicyState(options: {
91	  cwd: string;
92	  trustedFolder: boolean;
93	  interactive: boolean;
94	}): Promise<WorkspacePolicyState> {
95	  const { cwd, trustedFolder, interactive } = options;
96	
97	  let workspacePoliciesDir: string | undefined;
98	  let policyUpdateConfirmationRequest:
99	    | PolicyUpdateConfirmationRequest
100	    | undefined;
101	
102	  if (trustedFolder && !disableWorkspacePolicies) {
103	    const storage = new Storage(cwd);
104	
105	    // If we are in the home directory (or rather, our target Gemini dir is the global one),
106	    // don't treat it as a workspace to avoid loading global policies twice.
107	    if (storage.isWorkspaceHomeDir()) {
108	      return { workspacePoliciesDir: undefined };
109	    }
110	
111	    const potentialWorkspacePoliciesDir = storage.getWorkspacePoliciesDir();
112	    const integrityManager = new PolicyIntegrityManager();
113	    const integrityResult = await integrityManager.checkIntegrity(
114	      'workspace',
115	      cwd,
116	      potentialWorkspacePoliciesDir,
117	    );
118	
119	    if (integrityResult.status === IntegrityStatus.MATCH) {
120	      workspacePoliciesDir = potentialWorkspacePoliciesDir;
121	    } else if (
122	      integrityResult.status === IntegrityStatus.NEW &&
123	      integrityResult.fileCount === 0
124	    ) {
125	      // No workspace policies found
126	      workspacePoliciesDir = undefined;
127	    } else if (interactive && !autoAcceptWorkspacePolicies) {
128	      // Policies changed or are new, and we are in interactive mode and auto-accept is disabled
129	      policyUpdateConfirmationRequest = {
130	        scope: 'workspace',
131	        identifier: cwd,
132	        policyDir: potentialWorkspacePoliciesDir,
133	        newHash: integrityResult.hash,
134	      };
135	    } else {
136	      // Non-interactive mode or auto-accept is enabled: automatically accept/load
137	      await integrityManager.acceptIntegrity(
138	        'workspace',
139	        cwd,
140	        integrityResult.hash,
141	      );
142	      workspacePoliciesDir = potentialWorkspacePoliciesDir;
143	
144	      if (!interactive) {
145	        writeToStderr(
146	          'WARNING: Workspace policies changed or are new. Automatically accepting and loading them.\n',
147	        );
148	      } else {
149	        debugLogger.warn(
150	          'Workspace policies changed or are new. Automatically accepting and loading them.',
151	        );
152	      }
153	    }
154	  }
155	
156	  return { workspacePoliciesDir, policyUpdateConfirmationRequest };
